    ic.parent = ctrl;
    ic.property("ADBE Transform Group").property("ADBE Position").setValue([-cw / 2 + w * 0.075, 0]);

    var emo = _appleTxt(comp, "\uD83D\uDCAC", Math.round(w * 0.05), [1, 1, 1], false);
