        "Hozir\r\u2600\uFE0F\r31\u00B0", "15\r\u2600\uFE0F\r32\u00B0", "16\r\u26C5\r31\u00B0",
        "17\r\u26C5\r29\u00B0", "18\r\uD83C\uDF19\r26\u00B0"
