// --- STORY 7. SLOT MACHINE: reels stop one by one, jackpot
function _storySlot() {
    var comp = app.project.activeItem; if (!comp) return;
    var w = comp.width, h = comp.height, t0 = comp.time;
    var ctrl = _uiCtl(comp, "SLOT CONTROLLER", 6, [w / 2, h * 0.40]);
    ctrl.outPoint = comp.duration;
    var mw = w * 0.62, mh = w * 0.30, rw3 = mw * 0.26, rh3 = mh * 0.62;

    var body = _stRect(comp, "[Story] Slot Body", mw, mh, w * 0.035, [0.13, 0.145, 0.18, 1]);
    var bst3 = body.property("ADBE Root Vectors Group").property(1).property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Stroke");
    bst3.property("ADBE Vector Stroke Color").setValue([0.30, 0.32, 0.38, 1]);
    bst3.property("ADBE Vector Stroke Width").setValue(Math.max(3, w * 0.004));
    try { _uiShadow(body); } catch (e) {}
    body.parent = ctrl;
    body.property("ADBE Transform Group").property("ADBE Position").setValue([0, 0]);

    var lead = Math.round(w * 0.075);
    var strip = "\uD83C\uDF52\r7\r\uD83D\uDCB5\r\uD83C\uDF4B\r\uD83D\uDD14\r\uD83D\uDC8E\r7\r$";
    for (var rr = 0; rr < 3; rr++) {
        var rx = (rr - 1) * (rw3 + mw * 0.05);
        var win = _stRect(comp, "[Story] Reel Win " + (rr + 1), rw3, rh3, w * 0.015, [0.05, 0.06, 0.08, 1]);
        win.parent = ctrl;
        win.property("ADBE Transform Group").property("ADBE Position").setValue([rx, 0]);

        var matte = _stRect(comp, "[Story] Reel Matte " + (rr + 1), rw3, rh3, w * 0.015, [1, 1, 1, 1]);
        matte.parent = ctrl;
        matte.property("ADBE Transform Group").property("ADBE Position").setValue([rx, 0]);
        try { matte.enabled = false; } catch (e) {}

        var st3 = comp.layers.addText(strip);
        st3.name = "[Story] Reel Strip " + (rr + 1);
        st3.inPoint = t0; st3.outPoint = comp.duration;
        var sd3 = st3.property("Source Text").value;
        sd3.fontSize = Math.round(w * 0.045);
        sd3.fillColor = [0.95, 0.95, 0.98];
        try { sd3.justification = ParagraphJustification.CENTER_JUSTIFY; } catch (e) {}
        try { sd3.leading = lead; } catch (e) {}
        st3.property("Source Text").setValue(sd3);
        _appleFontTry(st3, _SF_BOLD);
        st3.parent = ctrl;
        var sp3 = st3.property("ADBE Transform Group").property("ADBE Position");
        var yTop = w * 0.016;
        sp3.setValueAtTime(t0 + 0.3, [rx, yTop]);
        sp3.setValueAtTime(t0 + 1.1 + rr * 0.55, [rx, yTop - lead * 7]);
        try {
            sp3.setTemporalEaseAtKey(1, [new KeyframeEase(0, 33)], [new KeyframeEase(0.7, 33)]);
            sp3.setTemporalEaseAtKey(2, [new KeyframeEase(0, 90)], [new KeyframeEase(0, 90)]);
        } catch (e) {}
        try { st3.setTrackMatte(matte, TrackMatteType.ALPHA); } catch (e) {}
    }

    var jp = _appleTxt(comp, "JACKPOT!", Math.round(w * 0.045), [0.95, 0.62, 0.12], true);
    _uiGlowFx(jp, w * 0.02, 0.7);
    jp.parent = ctrl;
    _stCenterAnchor(jp);
    jp.property("ADBE Transform Group").property("ADBE Position").setValue([0, mh * 0.78]);
    var jo = jp.property("ADBE Transform Group").property("ADBE Opacity");
    jo.setValueAtTime(t0 + 2.4, 0); jo.setValueAtTime(t0 + 2.55, 100);
    var js = jp.property("ADBE Transform Group").property("ADBE Scale");
    js.setValueAtTime(t0 + 2.4, [60, 60]);
    js.setValueAtTime(t0 + 2.6, [110, 110]);
    js.setValueAtTime(t0 + 2.75, [100, 100]);
    _appleEase(js);

    var sub3 = _appleTxt(comp, "banklar o'ynadi. siz to'ladingiz.", Math.round(w * 0.024), [0.62, 0.62, 0.68], false);
    sub3.parent = ctrl;
    _stCenterAnchor(sub3);
    sub3.property("ADBE Transform Group").property("ADBE Position").setValue([0, mh * 0.98]);
    var so3 = sub3.property("ADBE Transform Group").property("ADBE Opacity");
    so3.setValueAtTime(t0 + 2.8, 0); so3.setValueAtTime(t0 + 3.1, 100);
    ctrl.selected = true;
}

// --- GENESIS BLOCK: hex dump of bitcoin block #0, the embedded headline decodes in orange
function _genesisBlock() {
    var comp = app.project.activeItem;
    if(!comp) return;
    var dur = 8.5;
    var w = comp.width, h = comp.height;
    var ctrl = _uiCtl(comp, "GENESIS BLOCK CONTROLLER", dur, [w/2, h*0.42]);
    _addColorControl(ctrl, "Hex Green", [0.24,0.84,0.55]);
    _addColorControl(ctrl, "Headline Orange", [0.97,0.58,0.10]);
    var basePre = "var ctl=thisComp.layer('"+ctrl.name+"'); var spd=ctl.effect('Animation Speed')(1)/100; var t=(time-inPoint)*spd; ";

    var cw = w*0.88, pad = cw*0.065, fs = Math.round(cw*0.042), lh = fs*1.95;
    var ch = pad*2 + lh*9.6;
    var xL = -cw/2 + pad;
    function rowY(i){ return -ch/2 + pad + lh*(0.55 + i); }

    var card = _uiRRect(comp, "Genesis Window", dur, cw, ch, fs*0.8, '[0.016,0.024,0.018,1]');
    var cardStroke = card.property("ADBE Root Vectors Group").property(1).property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Stroke");
    cardStroke.property("ADBE Vector Stroke Color").setValue([0.13,0.20,0.15,1]);
    cardStroke.property("ADBE Vector Stroke Width").setValue(Math.max(2, w*0.0025));
    card.parent = ctrl;
    card.property("ADBE Transform Group").property("ADBE Position").setValue([0,0]);
    var cOp = card.property("ADBE Transform Group").property("ADBE Opacity");
    cOp.setValueAtTime(comp.time, 0); cOp.setValueAtTime(comp.time + 0.3, 92);

    function gLine(str, row, col, mode, delay, cps, glow) {
        var tl = _uiText(comp, str, fs, 6145, null, dur, col);
        _uiFont(tl, "Consolas");
        tl.parent = ctrl;
        tl.property("ADBE Transform Group").property("ADBE Position").setValue([xL, rowY(row)]);
        if (mode === "type") {
            var esc = str.replace(/'/g, "\\'");
            tl.property("ADBE Text Properties").property("ADBE Text Document").expression =
                basePre + "var s='"+esc+"'; var n=Math.floor(Math.max(0,(t-"+delay+")*"+cps+")); if(n>s.length)n=s.length; var o=s.substr(0,n); if(n<s.length&&n>0){o+='_';} text.sourceText.style.setText(o);";
        } else {
            tl.property("ADBE Transform Group").property("ADBE Opacity").expression = basePre + "(t>"+delay+")?100:0;";
        }
        if (glow) _uiGlowFx(tl, w*0.016, 0.6);
        return tl;
    }
    var DIM = [0.22,0.38,0.28], HASH = [0.24,0.84,0.55], HEX = [0.30,0.50,0.37], ORG = [0.97,0.58,0.10], WHT = [0.85,0.89,0.85];

    gLine("// blok #0 - genesis - 03/yan/2009", 0, DIM, "step", 0.4);
    gLine("hash: 000000000019d6689c085a...", 1, HASH, "step", 0.85);
    gLine("04 ff ff 00 1d 01 04 45 54 68", 2, HEX, "step", 1.25);
    gLine("65 20 54 69 6d 65 73 20 30 33", 3, HEX, "step", 1.5);
    gLine("2f 4a 61 6e 2f 32 30 30 39 20", 4, HEX, "step", 1.75);
    gLine("The Times 03/Jan/2009", 5.6, ORG, "type", 2.6, 17, true);
    gLine("Chancellor on brink of second", 6.6, ORG, "type", 4.1, 20, true);
    gLine("bailout for banks", 7.6, ORG, "type", 5.5, 18, true);
    gLine("abadiy yozildi. hech qachon o'chmaydi.", 8.8, WHT, "step", 6.9);

    ctrl.selected = true;
}

// --- BAILOUT STAMP: two official documents, APPROVED for banks / DENIED for people
function _bailoutStamp() {
    var comp = app.project.activeItem;
    if(!comp) return;
    var dur = 6.5;
    var w = comp.width, h = comp.height;
    var t0 = comp.time;
    var ctrl = _uiCtl(comp, "BAILOUT STAMP CONTROLLER", dur, [w/2, h*0.42]);
    var spdPre = "var ctl=thisLayer.parent ? thisLayer.parent : thisLayer; ";

    var cw = w*0.72, ch = cw*0.46, pad = cw*0.08;
    var PAPER = [0.93,0.90,0.82], INK = [0.14,0.12,0.09], BEIGE = [0.80,0.76,0.64];
    var GREENSTAMP = [0.10,0.50,0.24], REDSTAMP = [0.88,0.26,0.29];

    // camera-shake on the whole rig at each stamp slam
    ctrl.property("ADBE Transform Group").property("ADBE Position").expression =
        "var spd=effect('Animation Speed')(1)/100; var tt=(time-inPoint)*spd; " +
        "function shk(ts){var q=tt-ts; if(q<0) return [0,0]; var a=" + (w*0.014) + "*Math.exp(-q*8); return [a*Math.sin(q*42), a*Math.cos(q*31)];} " +
        "var a=shk(1.5), b=shk(3.3); value + [a[0]+b[0], a[1]+b[1]];";

    function centerAnchor(tl) {
        tl.property("ADBE Transform Group").property("ADBE Anchor Point").expression =
            "var r=sourceRectAtTime(time,false); [r.left+r.width/2, r.top+r.height/2];";
    }
    function fadeIn(L, d0, d1) {
        var op = L.property("ADBE Transform Group").property("ADBE Opacity");
        op.setValueAtTime(t0 + d0, 0);
        op.setValueAtTime(t0 + d1, 100);
    }

    function buildDoc(tag, yOff, rot, title, amount, stampStr, stampCol, stampDelay, stampRot, inD) {
        var dn = comp.layers.addNull(comp.duration);
        dn.name = "[Bailout] Doc " + tag;
        dn.inPoint = t0; dn.outPoint = t0 + dur;
        dn.property("ADBE Transform Group").property("ADBE Anchor Point").setValue([0,0]);
        dn.parent = ctrl;
        dn.property("ADBE Transform Group").property("ADBE Position").setValue([0, yOff]);
        dn.property("ADBE Transform Group").property("ADBE Rotate Z").setValue(rot);
        // slide-up entrance on the doc rig
        var dp = dn.property("ADBE Transform Group").property("ADBE Position");
        dp.setValueAtTime(t0 + inD, [0, yOff + ch*0.18]);
        dp.setValueAtTime(t0 + inD + 0.45, [0, yOff]);
        try { for (var k=1;k<=2;k++) dp.setTemporalEaseAtKey(k, [new KeyframeEase(0,75), new KeyframeEase(0,75)], [new KeyframeEase(0,75), new KeyframeEase(0,75)]); } catch(e){}

        var paper = _uiRRect(comp, "[Bailout] Paper " + tag, dur, cw, ch, cw*0.015, '[' + PAPER.join(',') + ',1]');
        try { _uiShadow(paper); } catch(e) {}
        paper.parent = dn;
        paper.property("ADBE Transform Group").property("ADBE Position").setValue([0, 0]);
        fadeIn(paper, inD, inD + 0.3);

        var ti = _uiText(comp, title, Math.round(cw*0.042), 6145, null, dur, [0.36,0.33,0.27]);
        _uiFont(ti, "TimesNewRomanPSMT");
        ti.parent = dn;
        ti.property("ADBE Transform Group").property("ADBE Position").setValue([-cw/2 + pad, -ch*0.28]);
        fadeIn(ti, inD + 0.1, inD + 0.4);

        var am = _uiText(comp, amount, Math.round(cw*0.082), 6145, null, dur, INK);
        _uiFont(am, "TimesNewRomanPS-BoldMT");
        am.parent = dn;
        am.property("ADBE Transform Group").property("ADBE Position").setValue([-cw/2 + pad, ch*0.06]);
        fadeIn(am, inD + 0.18, inD + 0.48);

        for (var li = 0; li < 2; li++) {
            var lw = cw * (li === 0 ? 0.62 : 0.44);
            var ln = _uiRRect(comp, "[Bailout] Line " + tag + li, dur, lw, Math.max(3, cw*0.008), 2, '[' + BEIGE.join(',') + ',1]');
            ln.parent = dn;
            ln.property("ADBE Transform Group").property("ADBE Position").setValue([-cw/2 + pad + lw/2, ch*(0.24 + li*0.1)]);
            fadeIn(ln, inD + 0.22, inD + 0.5);
        }

        // stamp: bordered box + text, slams in from 3x scale
        var sw_ = cw*0.5, sh_ = ch*0.36;
        var box = comp.layers.addShape();
        box.name = "[Bailout] Stamp " + tag;
        box.inPoint = t0; box.outPoint = t0 + dur;
        var bg = box.property("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
        var br = bg.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Rect");
        br.property("ADBE Vector Rect Size").setValue([sw_, sh_]);
        br.property("ADBE Vector Rect Roundness").setValue(sh_*0.14);
        var bst = bg.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Stroke");
        bst.property("ADBE Vector Stroke Color").setValue([stampCol[0], stampCol[1], stampCol[2], 1]);
        bst.property("ADBE Vector Stroke Width").setValue(Math.max(4, cw*0.016));
        box.parent = dn;
        box.property("ADBE Transform Group").property("ADBE Position").setValue([cw*0.20, ch*0.16]);
        box.property("ADBE Transform Group").property("ADBE Rotate Z").setValue(stampRot);
        box.property("ADBE Transform Group").property("ADBE Opacity").expression =
            "var spd=thisComp.layer('" + ctrl.name + "').effect('Animation Speed')(1)/100; ((time-inPoint)*spd>=" + stampDelay + ")?93:0;";
        box.property("ADBE Transform Group").property("ADBE Scale").expression =
            "var spd=thisComp.layer('" + ctrl.name + "').effect('Animation Speed')(1)/100; var t=(time-inPoint)*spd-" + stampDelay + "; " +
            "if(t<0){[300,300]}else{var s=100*(1+2*Math.exp(-13*t)+0.05*Math.sin(t*30)*Math.exp(-7*t)); [s,s];}";

        var stx = _uiText(comp, stampStr, Math.round(sw_*0.175), 6147, null, dur, stampCol);
        _uiFont(stx, "TimesNewRomanPS-BoldMT");
        centerAnchor(stx);
        stx.parent = box;
        stx.property("ADBE Transform Group").property("ADBE Position").setValue([0, 0]);
        stx.property("ADBE Transform Group").property("ADBE Opacity").expression =
            "var spd=thisComp.layer('" + ctrl.name + "').effect('Animation Speed')(1)/100; ((time-inPoint)*spd>=" + stampDelay + ")?93:0;";
        return dn;
    }

    buildDoc("A", -ch*0.72, -2, "Qutqaruv paketi - banklarga", "$700,000,000,000", "TASDIQLANDI", GREENSTAMP, 1.5, -12, 0.15);
    buildDoc("B", ch*0.72, 1.5, "Yordam so'rovi - oddiy aholi", "$0", "RAD ETILDI", REDSTAMP, 3.3, 8, 0.45);

    ctrl.selected = true;
}

// --- GROWTH CHART: line draws up to the right, dot pops, value rises
function _growthChart() {
    var comp = app.project.activeItem;
    if(!comp) return;
    var dur = 3.5;
    var w = comp.width, h = comp.height;
    var ctrl = _uiCtl(comp, "GROWTH CHART CONTROLLER", dur, [w*0.5, h*0.5]);
    _addColorControl(ctrl, "Line Color", [0.45,0.92,0.55]);
    _addColorControl(ctrl, "Text Color", [1,1,1]);
    _addSlider(ctrl, "Value", 70098);
    var pre = _uiPrefix(ctrl.name);
    var cRef = 'thisComp.layer("' + ctrl.name + '")';
    var cw = w*0.62, ch = w*0.5;
    var tip = [cw, -ch*0.92];

    // baseline axis
    var axis = _uiRRect(comp, "Chart Axis", dur, cw*1.05, Math.max(2,w*0.004), 0, cRef+'.effect("Text Color")(1)');
    axis.parent = ctrl;
    axis.property("ADBE Transform Group").property("ADBE Position").setValue([0, ch*0.06]);
    axis.property("ADBE Transform Group").property("ADBE Opacity").setValue(22);

    // the rising line
    var line = comp.layers.addShape();
    line.name = "Growth Line"; line.inPoint=comp.time; line.outPoint=comp.time+dur; line.motionBlur=true;
    var lg = line.property("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
    var pathG = lg.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Group");
    var shp = new Shape();
    shp.vertices = [[0,0],[cw*0.18,-ch*0.16],[cw*0.36,-ch*0.1],[cw*0.55,-ch*0.46],[cw*0.74,-ch*0.5],[cw*0.88,-ch*0.78],tip];
    shp.closed = false;
    pathG.property("ADBE Vector Shape").setValue(shp);
    var lstr = lg.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Stroke");
    lstr.property("ADBE Vector Stroke Color").expression = cRef+'.effect("Line Color")(1)';
    lstr.property("ADBE Vector Stroke Width").setValue(Math.max(5,w*0.013));
    lstr.property("ADBE Vector Stroke Line Cap").setValue(2);
    lstr.property("ADBE Vector Stroke Line Join").setValue(2);
    var ltrim = lg.property("ADBE Vectors Group").addProperty("ADBE Vector Filter - Trim");
    ltrim.property("ADBE Vector Trim End").expression = pre + "var e=eo3((t-0.1)/1.6); 100*Math.max(0,Math.min(1,e));";
    _uiGlowFx(line, w*0.02, 0.7);
    line.parent = ctrl;
    line.property("ADBE Transform Group").property("ADBE Position").setValue([-cw/2, ch*0.45]);

    // dot at tip
    var dot = comp.layers.addShape();
    dot.name = "Chart Dot"; dot.inPoint=comp.time; dot.outPoint=comp.time+dur; dot.motionBlur=true;
    var dg = dot.property("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
    var de = dg.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Ellipse");
    de.property("ADBE Vector Ellipse Size").setValue([w*0.04, w*0.04]);
    var df = dg.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
    df.property("ADBE Vector Fill Color").expression = cRef+'.effect("Line Color")(1)';
    _uiGlowFx(dot, w*0.03, 1.0);
    dot.parent = ctrl;
    dot.property("ADBE Transform Group").property("ADBE Position").setValue([-cw/2 + tip[0], ch*0.45 + tip[1]]);
    dot.property("ADBE Transform Group").property("ADBE Scale").expression = pre + "function el(x){var c=(2*Math.PI)/3;return x<=0?0:x>=1?1:Math.pow(2,-10*x)*Math.sin((x*10-0.75)*c)+1;} var e=el((t-1.5)/0.7); [e*100,e*100];";

    // value label near tip
    var val = _uiText(comp, "$0", Math.round(w*0.05), 6147, null, dur, [1,1,1]);
    val.property("ADBE Text Properties").property("ADBE Text Document").expression =
        "var ctl=thisComp.layer('"+ctrl.name+"'); var spd=ctl.effect('Animation Speed')(1)/100; var tt=(time-inPoint)*spd; "+FMT+
        "function eo3(x){x=Math.max(0,Math.min(1,x));return 1-Math.pow(1-x,3);} var e=eo3((tt-0.1)/1.7); var v=ctl.effect('Value')(1)*e; '$'+fmt(v);";
    _uiFont(val, "Arial-BoldMT");
    val.parent = ctrl;
    val.property("ADBE Transform Group").property("ADBE Position").setValue([-cw/2 + tip[0] - w*0.05, ch*0.45 + tip[1] - w*0.085]);
    val.property("ADBE Transform Group").property("ADBE Opacity").expression = _uiFade(pre, 0.32);

    ctrl.selected = true;
}

