    var comp = app.project.activeItem;
    if(!comp) return;
    var dur = 4.0;
    var w = comp.width, h = comp.height;
    var ctrl = _uiCtl(comp, "RECHARGE CONTROLLER", dur, [w/2, h*0.5]);
    _addColorControl(ctrl, "Charge Color", [1,0.32,0.12]);
