// --- 6) APPLE SOFT SHADOW: tanlanganlarga (distance 0, katta softness, ~12%) ---
function _apShadow() {
    var comp = app.project.activeItem;
    var sel = comp.selectedLayers;
    if (sel.length===0){ alert("Avval layer(lar)ni tanlang!"); return; }
    var s=comp.height/1920;
    for (var i=0;i<sel.length;i++){
        try{
            var ds=sel[i].property("ADBE Effect Parade").addProperty("ADBE Drop Shadow");
            try{ ds.property("ADBE Drop Shadow-0002").setValue(32); }catch(e){}
            try{ ds.property("ADBE Drop Shadow-0004").setValue(0); }catch(e){}
            try{ ds.property("ADBE Drop Shadow-0005").setValue(130*s); }catch(e){}
        }catch(e){}
    }
    return sel.length;
}

// ============================================================
// ATERMAGICS BOUNCE (v2.29) - foydalanuvchi bergan bounce (easeOut factor bilan).
// Tanlangan layer(lar)ning KEYFRAME QO'YILGAN transform xossalariga bir bosishda tushadi.
var AM_BOUNCE = "amp=.04;freq=1.8;decay=3;n=0;time_max=3;" +
    "if(numKeys>0){n=nearestKey(time).index;if(key(n).time>time){n--;}}" +
    "if(n==0){t=0;}else{t=time-key(n).time;}" +
    "if(n>0&&t<time_max){v=velocityAtTime(key(n).time-thisComp.frameDuration/10);" +
    "easeFactor=easeOut(t,0,time_max,1,0);" +
    "value+v*amp*Math.sin(freq*t*2*Math.PI)/Math.exp(decay*t)*easeFactor;}else{value;}";
function _amBounce() {
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) { alert("Komp oching"); return; }
    var sel = comp.selectedLayers;
    if (sel.length === 0) { alert("Layer tanlang"); return; }
    app.beginUndoGroup("AterMagics Bounce");
    var applied = 0;
    for (var i = 0; i < sel.length; i++) {
        var L = sel[i];
        var props = ["ADBE Position", "ADBE Scale", "ADBE Rotate Z", "ADBE Anchor Point"];
        for (var p = 0; p < props.length; p++) {
            try {
                var pr = L.property("ADBE Transform Group").property(props[p]);
                if (pr && pr.numKeys > 0 && pr.canSetExpression) {
                    pr.expression = AM_BOUNCE;
                    applied++;
                }
            } catch (e) {}
        }
    }
    app.endUndoGroup();
    if (applied === 0) alert("Keyframe topilmadi - avval harakatga 2ta key qo'ying");
}

// PAPER SEARCH (v2.30) - SIMONS videosidagi search-pill: oq pill + caret bilan yozilish + SEARCHING label
function _srchPaper() {
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) { alert("Komp oching"); return; }
    var q = prompt("Nima yozilsin?", "90% win rate");
    if (q === null) return;
    if (q === "") q = "90% win rate";
    app.beginUndoGroup("Paper Search");
    var t0 = comp.time, W = comp.width, H = comp.height;
    var cx = W / 2, cy = H / 2 - 30;
    var INKC = [0.067, 0.078, 0.090];
    // pill
    var pill = comp.layers.addShape(); pill.name = "[SRCH] pill";
    var pg = pill.property("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
    var pr = pg.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Rect");
    pr.property("ADBE Vector Rect Size").setValue([W * 0.7, 120]);
    pr.property("ADBE Vector Rect Roundness").setValue(60);
    var pf = pg.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
    pf.property("ADBE Vector Fill Color").setValue([1, 1, 1]);
    var ps = pg.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Stroke");
    ps.property("ADBE Vector Stroke Color").setValue([0.85, 0.84, 0.80]);
    ps.property("ADBE Vector Stroke Width").setValue(3);
    pill.position.setValue([cx, cy]);
    pill.inPoint = t0; pill.outPoint = t0 + 4;
    pill.scale.setValueAtTime(t0, [62, 62]);
    pill.scale.setValueAtTime(t0 + 0.26, [100, 100]);
    try { pill.scale.expression = AM_BOUNCE; } catch (eB) {}
    pill.opacity.setValueAtTime(t0, 0); pill.opacity.setValueAtTime(t0 + 0.1, 100);
    // typing text
    var ty = comp.layers.addText("");
    ty.name = "[SRCH] text";
    var td = ty.property("Source Text").value;
    td.resetCharStyle(); td.fontSize = 44; td.applyFill = true; td.fillColor = INKC; td.applyStroke = false;
    td.font = "ArialMT"; td.justification = ParagraphJustification.CENTER_JUSTIFY;
    ty.property("Source Text").setValue(td);
    ty.position.setValue([cx, cy + 16]);
    ty.inPoint = t0; ty.outPoint = t0 + 4;
    var st = ty.property("Source Text");
    var tt = t0 + 0.25;
    for (var i = 1; i <= q.length; i++) {
        var d2 = st.valueAtTime(tt, false); d2.text = q.substring(0, i) + "|";
        st.setValueAtTime(tt, d2); tt += 0.085;
    }
    var d3 = st.valueAtTime(tt + 0.1, false); d3.text = q; st.setValueAtTime(tt + 0.1, d3);
    for (i = 1; i <= st.numKeys; i++) { st.setInterpolationTypeAtKey(i, KeyframeInterpolationType.HOLD); }
    // SEARCHING label
    var lb = comp.layers.addText("SEARCHING...");
    lb.name = "[SRCH] label";
    var td2 = lb.property("Source Text").value;
    td2.resetCharStyle(); td2.fontSize = 28; td2.applyFill = true; td2.fillColor = [0.55, 0.55, 0.55]; td2.applyStroke = false;
    td2.font = "ArialMT"; td2.justification = ParagraphJustification.CENTER_JUSTIFY; td2.tracking = 700;
    lb.property("Source Text").setValue(td2);
    lb.position.setValue([cx, cy + 160]);
    lb.inPoint = t0 + 0.2; lb.outPoint = t0 + 4;
    lb.position.setValueAtTime(t0 + 0.2, [cx, cy + 200]);
    lb.position.setValueAtTime(t0 + 0.5, [cx, cy + 160]);
    try { lb.position.expression = AM_BOUNCE; } catch (eB2) {}
    lb.opacity.setValueAtTime(t0 + 0.2, 0); lb.opacity.setValueAtTime(t0 + 0.35, 100);
    app.endUndoGroup();
}

// SAAS KIT (v2.32) - user's own Main.aep transitions ported (D:\ae lrn\Transition Project File)
// All keyframes left open for hand-editing. Numbers taken from the dumped project.
function _saasSel(minN) {
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) { alert("Komp oching"); return null; }
    var sel = comp.selectedLayers;
    if (sel.length < minN) { alert(minN + " ta layer tanlang"); return null; }
    return { c: comp, s: sel };
}
// T-1..T-6 stack: staggered Block Dissolve + CC Ball Action + rang variantlari
function _saasBallReveal() {
    var ctx = _saasSel(1); if (!ctx) return;
    app.beginUndoGroup("SaaS Ball Reveal");
    var comp = ctx.c, src = ctx.s[0], t0 = comp.time;
    var stag = 0.42, durD = 1.5;
    for (var i = 5; i >= 0; i--) { // pastdan tepaga: eng erta pastda
        var L = src.duplicate();
        L.name = "[SAAS] T-" + (i + 1);
        L.startTime = src.startTime; // vaqtni buzmaslik
        L.inPoint = t0 + stag * i;
        L.outPoint = Math.min(t0 + stag * i + 6, comp.duration);
        var fx = L.property("ADBE Effect Parade");
        var bd = fx.addProperty("ADBE Block Dissolve");
        var endV = (i === 5) ? 18 : 0; // T-6 qismiy qoladi (asl loyihadagidek)
        bd.property("ADBE Block Dissolve-0001").setValueAtTime(L.inPoint, 100);
        bd.property("ADBE Block Dissolve-0001").setValueAtTime(L.inPoint + durD, endV);
        try { fx.addProperty("CC Ball Action"); } catch (eB) {}
        if (i % 3 === 0) {
            var tn = fx.addProperty("ADBE Tint"); tn.property("ADBE Tint-0003").setValue(60);
        } else if (i % 3 === 1) {
            try { fx.addProperty("APC Colorama"); } catch (eC) {}
        } else {
            try { fx.addProperty("ADBE Invert"); } catch (eI) {}
            try { fx.addProperty("APC Colorama"); } catch (eC2) {}
        }
        L.moveBefore(src);
    }
    src.enabled = true;
    app.endUndoGroup();
}
// kursor uchib kelib tanlangan "tugma"ni bosadi
function _saasCursorClick() {
    var ctx = _saasSel(1); if (!ctx) return;
    app.beginUndoGroup("SaaS Cursor Click");
    var comp = ctx.c, tgt = ctx.s[0], t0 = comp.time;
    var tp = tgt.position.value;
    var cur = comp.layers.addShape(); cur.name = "[SAAS] cursor";
    var g = cur.property("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
    var pth = g.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Group");
    var sh = new Shape();
    sh.vertices = [[0,0],[0,58],[14,45],[23,64],[31,60],[22,42],[40,40]];
    sh.closed = true;
    pth.property("ADBE Vector Shape").setValue(sh);
    var fl = g.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
    fl.property("ADBE Vector Fill Color").setValue([0.08, 0.08, 0.1]);
    var st = g.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Stroke");
    st.property("ADBE Vector Stroke Color").setValue([1, 1, 1]);
    st.property("ADBE Vector Stroke Width").setValue(4);
    cur.inPoint = t0; cur.outPoint = Math.min(t0 + 3, comp.duration);
    // uchish: past-chapdan targetga (Main comp qiymatlari: 1.0s, rot 101->22)
    cur.position.setValueAtTime(t0, [tp[0] - 620, tp[1] + 480]);
    cur.position.setValueAtTime(t0 + 1.0, [tp[0] + 8, tp[1] + 10]);
    cur.rotation.setValueAtTime(t0, 101);
    cur.rotation.setValueAtTime(t0 + 1.0, 22);
    // klik: dip (asl: 8->4->8 = 50% dip, 0.16s)
    cur.scale.setValueAtTime(t0 + 1.0, [100, 100]);
    cur.scale.setValueAtTime(t0 + 1.08, [55, 55]);
    cur.scale.setValueAtTime(t0 + 1.16, [100, 100]);
    // target javob-punch: RELATIVE (asl: 31->28->31 = ~10% dip)
    var b = tgt.scale.value;
    tgt.scale.setValueAtTime(t0 + 1.0, [b[0], b[1]]);
    tgt.scale.setValueAtTime(t0 + 1.08, [b[0] * 0.9, b[1] * 0.9]);
    tgt.scale.setValueAtTime(t0 + 1.18, [b[0], b[1]]);
    // ease: Soft Flow
    try {
        var e = new KeyframeEase(0, 75);
        cur.position.setTemporalEaseAtKey(1, [e, e], [e, e]);
        cur.position.setTemporalEaseAtKey(2, [e, e], [e, e]);
    } catch (eE) {}
    app.endUndoGroup();
}
// tanlangan layerlar chapdan stagger bilan kiradi (Main: 563px, 1.0s, ~0.09s stagger)
function _saasStagger() {
    var ctx = _saasSel(2); if (!ctx) return;
    app.beginUndoGroup("SaaS Stagger Slide");
    var comp = ctx.c, sel = ctx.s, t0 = comp.time;
    for (var i = 0; i < sel.length; i++) {
        var L = sel[i];
        var p = L.position.value;
        var ts = t0 + 0.09 * i;
        L.position.setValueAtTime(ts, [p[0] - 563, p[1], p[2] || 0]);
        L.position.setValueAtTime(ts + 1.0, p);
        L.opacity.setValueAtTime(ts, 0);
        L.opacity.setValueAtTime(ts + 0.25, 100);
        try {
            var e = new KeyframeEase(0, 75);
            var n = L.position.numKeys;
            L.position.setTemporalEaseAtKey(n - 1, [e, e], [e, e]);
            L.position.setTemporalEaseAtKey(n, [e, e], [e, e]);
        } catch (eE) {}
    }
    app.endUndoGroup();
}
